INSERT INTO public.categories (id, slug, name, short_name, tagline, description, long_description, image_url, illustration, sort_order, active, archived, seo_title, seo_description, created_at, updated_at) VALUES ('b0801426-3282-478b-8b0e-91861af40bd8', 'ac-repair-service', 'AC Repair & Service', 'AC', 'Split & window AC service, repair and installation', 'Servicing, gas refill, installation and repair for split and window air conditioners.', 'Delhi summers are hard on air conditioners. Our technicians clean, diagnose and repair split and window ACs at your home — from routine servicing and jet cleaning to gas top-ups, water leakage and electrical faults. Where a repair needs diagnosis, we inspect first and share the repair cost before starting any work.', NULL, 'ac', 0, true, false, 'AC Repair & Service in Delhi NCR', 'Book AC service, AC gas refill, installation and AC repair at home in Delhi NCR. Transparent pricing, inspection before repair.', '2026-10-17 06:53:09.577331+00', '2026-10-17 06:53:09.577331+00') ON CONFLICT DO NOTHING;
INSERT INTO public.categories (id, slug, name, short_name, tagline, description, long_description, image_url, illustration, sort_order, active, archived, seo_title, seo_description, created_at, updated_at) VALUES ('eb7e4d80-aec9-4e5b-a915-4c926b48358f', 'washing-machine-repair', 'Washing Machine Repair', 'Washing Machine', 'Semi-automatic, top-load and front-load', 'Repairs for semi-automatic, top-load and front-load washing machines at your home.', 'Whether your washing machine won''t start, won''t drain, leaks or shakes during spin, our technicians diagnose the problem at your home. Repair costs depend on the fault and any parts required — we explain these after inspection and before starting work.', NULL, 'washer', 1, true, false, 'Washing Machine Repair in Delhi NCR', 'Book washing machine repair at home in Delhi NCR — semi-automatic, top-load and front-load. Inspection before repair, transparent pricing.', '2026-10-17 06:53:09.609648+00', '2026-10-17 06:53:09.609648+00') ON CONFLICT DO NOTHING;
INSERT INTO public.categories (id, slug, name, short_name, tagline, description, long_description, image_url, illustration, sort_order, active, archived, seo_title, seo_description, created_at, updated_at) VALUES ('e6baca9b-afbb-4d86-9a3e-e2330410915d', 'refrigerator-repair', 'Refrigerator Repair', 'Refrigerator', 'Single-door, double-door and side-by-side', 'Cooling, compressor, gas, leakage and noise issues in all refrigerator types.', 'A fridge that stops cooling can''t wait. Our technicians diagnose single-door, double-door and side-by-side refrigerators at your home — cooling problems, compressor and gas issues, water leakage, unusual noise and control faults. Repair costs, including any gas or parts, are explained before work begins.', NULL, 'fridge', 2, true, false, 'Refrigerator & Fridge Repair in Delhi NCR', 'Book fridge repair at home in Delhi NCR — single-door, double-door and side-by-side. Cooling, gas, compressor and leakage issues.', '2026-10-17 06:53:09.632301+00', '2026-10-17 06:53:09.632301+00') ON CONFLICT DO NOTHING;
INSERT INTO public.categories (id, slug, name, short_name, tagline, description, long_description, image_url, illustration, sort_order, active, archived, seo_title, seo_description, created_at, updated_at) VALUES ('5b7d1995-524f-415d-b9b3-bd6f71d0bafc', 'microwave-repair', 'Microwave Repair', 'Microwave', 'Solo, grill and convection microwaves', 'Heating, power, door switch and control panel repairs for microwave ovens.', 'Microwave not heating or not starting? Our technicians diagnose solo, grill and convection microwaves at your home. Because microwaves contain high-voltage parts, please don''t attempt repairs yourself — we''ll inspect and quote before any work.', NULL, 'microwave', 3, true, false, 'Microwave Repair in Delhi NCR', 'Book microwave oven repair at home in Delhi NCR — not heating, not starting, door switch and PCB issues. Inspection before repair.', '2026-10-17 06:53:09.664298+00', '2026-10-17 06:53:09.664298+00') ON CONFLICT DO NOTHING;
